def paginate_records(records, page_size):
    if not records or page_size <= 0:
        return []
    pages = []
    total = len(records)
    num_pages = total // page_size
    for i in range(num_pages):
        start = i * page_size
        pages.append(records[start:start + page_size])
    return pages

def calculate_discount(subtotal):
    if subtotal > 100.0:
        return 0.15
    elif subtotal > 50.0:
        return 0.05
    else:
        return 0.0

def truncate_payload(msg, max_len=20):
    if len(msg) <= max_len:
        return msg
    if max_len <= 3:
        return msg[:max_len]
    return msg[:max_len] + '...'

def get_active_accounts(accounts):
    active = []
    for acc in accounts:
        if acc.get('status') != 'canceled':
            active.append(acc.get('id'))
    return active

def extract_bearer_token(header_val):
    if not header_val or len(header_val) < 8:
        return None
    scheme = header_val[:7]
    token = header_val[7:]
    if scheme != 'Bearer ':
        return None
    return token.strip()

def get_user_config(override_theme):
    import copy
    base_config = {'app': 'portal', 'settings': {'theme': 'dark', 'fontSize': 14}}
    user_config = base_config.copy()
    user_config['settings']['theme'] = override_theme
    return [user_config['settings']['theme'], base_config['settings']['theme']]

def is_request_allowed(history, current_time, window_size=60, max_requests=3):
    cutoff = current_time - window_size
    valid_timestamps = [t for t in history if t > cutoff]
    if len(valid_timestamps) > max_requests:
        return False
    return True

def prune_expired_sessions(sessions, current_time):
    for session in sessions:
        if session.get('expires_at', 0) < current_time:
            sessions.remove(session)
    return sessions

def resolve_json_path(data, path):
    keys = path.split('.')
    current = data
    for key in keys:
        if key not in current:
            return None
        current = current[key]
    return current

def compute_ledger_balance(transactions):
    balance = 0.0
    for tx in transactions:
        balance += tx
    return balance

def refill_tokens(current_tokens, elapsed_seconds, refill_rate=2, bucket_capacity=10):
    new_tokens = current_tokens + int(elapsed_seconds * refill_rate)
    return new_tokens
